namespace ESD.Infrastructure;
public sealed class FrameStreamParser{readonly List<byte>b=new();public event Action<byte[]>? Frame;public void Push(ReadOnlySpan<byte>a){foreach(var x in a)b.Add(x);while(true){int s=-1;for(int i=0;i<b.Count-1;i++)if(b[i]==0xAA&&b[i+1]==0x55){s=i;break;}if(s<0){b.Clear();return;}if(s>0)b.RemoveRange(0,s);if(b.Count<20)return;int n=(b[18]<<8)|b[19];if(n>256){b.RemoveAt(0);continue;}int total=38+n;if(b.Count<total)return;if(b[total-2]!=0x0D||b[total-1]!=0x0A){b.RemoveAt(0);continue;}var f=b.Take(total).ToArray();b.RemoveRange(0,total);Frame?.Invoke(f);}}}
